SELECT 
FROM comments c JOIN users u ON u.id = c.user_id
WHERE c.id = #{id}

SELECT 
FROM comments c JOIN users u ON u.id = c.user_id

    c.post_id = #{postId}

        AND (c.created_at, c.id) > (#{cursorCreatedAt}, #{cursorId})


ORDER BY c.created_at, c.id
LIMIT #{limit}

SELECT COUNT(*)
FROM comments
WHERE post_id = #{postId}
